{"sql": "WITH stats AS (
  SELECT AVG("loss_rate_%") as avg_lr, STDDEV("loss_rate_%") as std_lr
  FROM veg_loss_rate_df
)
SELECT "loss_rate_%" FROM veg_loss_rate_df, stats
WHERE ABS("loss_rate_%" - (avg_lr - std_lr)) < 0.001 OR ABS("loss_rate_%" - (avg_lr + std_lr)) < 0.001"}

{"sql": "WITH stats AS (
  SELECT AVG("loss_rate_%") as avg_lr, STDDEV("loss_rate_%") as std_lr
  FROM veg_loss_rate_df
)
SELECT avg_lr, std_lr, avg_lr - std_lr as lower, avg_lr + std_lr as upper FROM stats"}
